#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char *argv[])
{
    const char *NO_INPUT = "NO_INPUT";
    const char *BAD_INPUT = "BAD_INPUT";
    const char *OUT_OF_RANGE = "OUT_OF_RANGE";
    const char *STEP_LIMIT_EXCEEDED = "STEP_LIMIT_EXCEEDED";
    const char *OVERFLOW_GUARD = "OVERFLOW_GUARD";

    if (argc < 2) {
        puts(NO_INPUT);
        return 0;
    }

    char *endptr = NULL;
    errno = 0;
    long n = strtol(argv[1], &endptr, 10);

    if (endptr == argv[1] || *endptr != '\0') {
        puts(BAD_INPUT);
        return 0;
    }

    if (n < 1) {
        puts(BAD_INPUT);
        return 0;
    }
    if (n > 1000000000L) {
        puts(OUT_OF_RANGE);
        return 0;
    }

    const long STEP_LIMIT = 999999L;
    const long OVERFLOW_LIMIT = 1000000000000000L; // 1e15

    long cur = n;
    long steps = 0;

    while (1) {
        if (cur == 1) {
            printf("n=%ld steps=%ld\n", n, steps);
            break;
        }
        if (steps > STEP_LIMIT) {
            puts(STEP_LIMIT_EXCEEDED);
            break;
        }
        if (cur > OVERFLOW_LIMIT) {
            puts(OVERFLOW_GUARD);
            break;
        }
        if ((cur & 1L) == 0) {
            cur = cur >> 1;
        } else {
            unsigned long long tmp = (unsigned long long)cur * 3ULL + 1ULL;
            cur = (long)tmp;
        }
        ++steps;
    }
    return 0;
}
